#include "h3/game.hpp"
#include <algorithm>
#include <fstream>
#include <iostream>
#include <stdexcept>
using namespace h3;
int main(){int checks=0;auto check=[&](bool value,const char*message){if(!value)throw std::runtime_error(message);++checks;};try{
 auto fixture=[](){auto g=Game::create();g.hero.army={Stack{Pikeman,100},Stack{Archer,50}};g.hero.skills={};g.hero.spellbook=true;g.hero.spells.fill(true);g.hero.mana=500;g.hero.power=2;g.objectById(15)->army={Stack{Pikeman,5},Stack{Archer,100}};g.startBattle(15);g.battle->units[0].x=4;g.battle->units[0].y=5;g.battle->units[1].x=3;g.battle->units[1].y=3;g.battle->units[2].x=8;g.battle->units[2].y=5;g.battle->units[3].x=12;g.battle->units[3].y=9;g.battle->queue={0,1,100,101};return g;};
 {auto g=fixture();check(g.cast(Hypnotize,{8,5}).empty()&&g.battle->units[2].team==0,"Hypnotize failed to transfer control");check(g.battle->units[2].id==100&&g.validate(),"Hypnotize corrupted identity, footprint or save validation");auto p=std::filesystem::temp_directory_path()/"h3-hypnosis-roundtrip.json";std::string error;check(g.save(p,error),error.c_str());Game loaded;check(loaded.load(p,error)&&loaded.toJson()==g.toJson(),"Hypnotize did not survive save/load");std::filesystem::remove(p);g.battle->spellRound=0;check(g.cast(Cure,{8,5}).empty()&&g.battle->units[2].team==1,"Cure failed to return hypnotized enemy");}
 {auto g=fixture();auto before=g.toJson();check(!g.cast(Hypnotize,{12,9}).empty()&&g.toJson()==before,"Hypnotize accepted excess hit points or charged on rejection");}
 {auto g=fixture();g.hero.skills[EarthMagic]=g.hero.skills[AirMagic]=g.hero.skills[WaterMagic]=3;check(g.cast(ForceField,{6,7}).empty()&&g.battle->obstacles.front().cells.size()==3,"Expert Force Field shape missing");check(!g.battlePath(g.battle->units[0],{6,7}),"Force Field allowed landing on a blocked tile");g.battle->spellRound=0;check(g.cast(RemoveObstacle,{6,7}).empty()&&g.battle->obstacles.empty(),"Expert Remove Obstacle did not clear Force Field");check(g.battlePath(g.battle->units[0],{6,7}).has_value(),"Removed obstacle still blocks pathfinding");}
 {auto g=fixture();BattleObstacle stone;stone.spell=-1;stone.cells={{6,5}};g.battle->obstacles.push_back(stone);check(!g.battlePath(g.battle->units[0],{6,5}),"Natural obstacle has no collision");check(g.cast(RemoveObstacle,{6,5}).empty()&&g.battle->obstacles.empty(),"Unskilled Remove Obstacle failed on a natural obstacle");}
 {auto g=fixture();g.battle->obstacles.push_back({Quicksand,1,2,0,-1,2,{{5,5}}});check(g.act("attack",{8,5}).empty()&&g.battle->units[0].x==5&&g.battle->units[0].y==5,"Quicksand did not stop a moving attacker");check(g.battle->units[2].hp==50,"Attacker struck an enemy after hidden quicksand stopped it");check(g.battle->obstacles.front().revealed==3,"Triggered quicksand was not revealed");}
 {auto g=fixture();g.battle->obstacles.push_back({LandMine,1,2,0,-1,2,{{5,5}}});int hp=g.battle->units[0].hp;check(g.act("move",{5,5}).empty(),"Could not enter hidden mine");check(g.battle->units[0].hp==hp-45&&g.battle->obstacles.empty(),"Mine damage differs from 10*power+25 or mine did not disappear");}
 {auto g=fixture();g.battle->obstacles.push_back({LandMine,0,2,0,-1,1,{{5,5}}});int hp=g.battle->units[0].hp;g.act("move",{5,5});check(g.battle->units[0].hp==hp&&g.battle->obstacles.size()==1,"Friendly unit triggered its own mine");}
 for(int mastery=0;mastery<4;++mastery){auto g=fixture();g.hero.skills[FireMagic]=mastery;check(g.cast(LandMine).empty()&&g.battle->obstacles.size()==size_t(std::array<int,4>{4,4,6,8}[mastery]),"Land Mine patch count differs from original");}
 {auto g=fixture();g.battle->obstacles.push_back({FireWall,1,2,0,2,3,{{5,5}}});int hp=g.battle->units[0].hp;g.act("move",{5,5});check(g.battle->units[0].hp==hp-30,"Firewall did not damage a crossing stack");}
 {auto g=fixture();g.hero.originalId=136;g.battle->obstacles.push_back({FireWall,0,2,0,2,3,{{5,5}}});int hp=g.battle->units[0].hp;g.act("move",{5,5});check(g.battle->units[0].hp==hp-60,"Luna's Firewall specialty did not double damage");}
 {auto g=fixture();check(g.cast(Teleport,{4,5},{10,1}).empty()&&g.battle->units[0].x==10&&g.battle->units[0].y==1,"Teleport failed to move selected stack to selected tile");check(g.battle->units[0].acted==false,"Teleport incorrectly spent the creature action");}
 {auto g=fixture();g.hero.skills[FireMagic]=3;check(g.cast(Berserk,{4,5}).empty()&&g.battle->units[0].effects[Berserk]>0,"Berserk failed on a living allied unit");g.hero.spellbook=false;g.battle->units[1].x=5;g.battle->units[1].y=5;g.battle->queue={0,1,100,101};int hp=g.battle->units[1].hp;g.ai();check(g.battle->units[1].hp<hp&&g.battle->units[0].effects[Berserk]==0,"Berserk did not attack nearest allied stack and expire");}
 {auto g=fixture();g.hero.spellbook=false;g.battle->units[0].count=g.battle->units[0].initialCount=g.battle->units[0].permanentCount=1;g.battle->units[0].hp=10;g.battle->units[0].x=7;g.battle->units[0].y=5;g.battle->lastDamageRound=0;g.battle->round=4;int hp=g.battle->units[2].hp;g.ai();check(!g.battle||g.battle->units[2].hp<hp,"Automatic battle kept shuffling without damage");}
 auto adventure=[](){auto g=Game::create();g.objects.clear();g.decorations.clear();for(auto&t:g.tiles){t.blocked=false;t.decor=Decor::None;t.terrain=Terrain::Grass;t.seen=true;}g.hero.pos={4,10};g.hero.army={Stack{Pikeman,10}};g.hero.spellbook=true;g.hero.spells.fill(true);g.hero.mana=500;g.hero.skills={};return g;};
 {auto g=adventure();g.tile({5,10})->terrain=Terrain::Water;g.hero.skills[WaterMagic]=3;int mana=g.hero.mana;check(g.castAdventure(SummonBoat).empty()&&g.hero.mana==mana-g.spellCost(SummonBoat),"Expert Summon Boat did not charge mana");auto*boat=g.objectAt({5,10});check(boat&&boat->type==ObjectType::Boat,"Expert Summon Boat did not create a ship");check(g.castAdventure(ScuttleBoat,{5,10}).empty()&&!g.objectAt({5,10}),"Expert Scuttle Boat did not remove ship");}
 {auto g=adventure();g.hero.skills[AirMagic]=3;check(g.castAdventure(DimensionDoor,{12,10}).empty()&&g.hero.pos==Point{12,10}&&g.hero.movement==1360,"Dimension Door position or expert cost incorrect");for(int i=0;i<3;++i)check(g.castAdventure(DimensionDoor,{i%2?12:4,10}).empty(),"Expert Dimension Door rejected one of four daily casts");auto before=g.toJson();check(!g.castAdventure(DimensionDoor,{12,10}).empty()&&g.toJson()==before,"Fifth Dimension Door cast charged or moved hero");}
 for(int spell:{Visions,Disguise,Fly,WaterWalk,ViewEarth,ViewAir}){auto g=adventure();auto fog=g.tiles;check(g.castAdventure(spell).empty()&&g.adventureSpellActive(spell),"Adventure spell did not activate");bool unchanged=true;for(size_t i=0;i<fog.size();++i)unchanged&=fog[i].seen==g.tiles[i].seen;check(unchanged,"View spell permanently revealed fog");++g.day;check(!g.adventureSpellActive(spell),"One-day spell survived new day");}
 for(int spell:{Fly,WaterWalk}){auto g=adventure();for(int y=0;y<g.mapHeight;++y)g.tile({5,y})->terrain=Terrain::Water;g.hero.skills[spell==Fly?AirMagic:WaterMagic]=3;g.castAdventure(spell);auto route=g.magicRoute({6,10});check(route.size()==2&&route[0].cost+route[1].cost==200,"Expert crossing cost or route incorrect");g.move({6,10});check(g.hero.pos==Point{6,10}&&!g.hero.onBoat&&g.hero.movement==1360,"Magic crossing boarded a ship or lost remaining movement");g.hero.movement=99;check(g.magicRoute({4,10}).empty(),"Magic route could strand hero without enough movement to land");}
 {Game g;std::string error;check(g.importScenario(std::filesystem::path(H3_TEST_SOURCE_ROOT)/"assets/demo/scenarios/seven-lakes-1.json",error),error.c_str());g.hero.spellbook=true;g.hero.spells[TownPortal]=true;g.hero.mana=100;g.hero.skills[EarthMagic]=3;Point home=g.town.pos;g.hero.pos={home.x+3,home.y};g.storeHero();int gold=g.resources[Gold];check(g.castAdventure(TownPortal).empty()&&g.hero.pos==home&&g.hero.movement==1360,"Town Portal failed to return to own town");check(g.resources[Gold]==gold,"Town Portal changed kingdom resources");check(g.validate(),"Town Portal left an invalid roster or town state");}
 std::cout<<checks<<" spell completion checks passed\n";return 0;
 }catch(const std::exception&e){std::cerr<<"Spell completion after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}}
